/**
 * Fonts bundled with the window, inline so the page needs no file path (it loads as a data: page).
 * Newsreader (serif, variable weight, roman and italic) and Schibsted Grotesk (sans, variable weight):
 * both SIL Open Font License 1.1, recorded in docs/baton/THIRD_PARTY_NOTICES.md. Latin subset only.
 * Bricolage Grotesque (sans, variable weight), the Lively pill design's face, is OFL 1.1 too.
 */
const face = (family: string, style: string, base64: string, weight: string) =>
  `@font-face{font-family:"${family}";font-style:${style};font-weight:${weight};font-display:block;src:url(data:font/woff2;base64,${base64}) format("woff2")}`;

const FACES = [
  face(
    "Newsreader",
    "normal",
    "",
    "200 800",
  ),
  face(
    "Newsreader",
    "italic",
    "",
    "200 800",
  ),
  face(
    "Schibsted Grotesk",
    "normal",
    "",
    "400 900",
  ),
];

export const FONT_FACES = FACES.join("\n");

/** The faces each pill design draws with: Tessaya's own and his words; Lively's; Quiet uses the system's. */
export const PILL_FACES = {
  tessaya: `${FACES[0]}\n${FACES[2]}`,
  quiet: "",
  lively: face(
    "Bricolage Grotesque",
    "normal",
    "",
    "200 800",
  ),
} as const;
